def itch_message(
    tag: str,
    stock_locate: int,
    tracking_number: int,
    timestamp: int,
    body: bytes,
) -> bytes:
    payload = (
        tag.encode("ascii")
        + pack(">HH", stock_locate, tracking_number)
        + timestamp.to_bytes(6, "big")
        + body
    )
    return pack(">H", len(payload)) + payload


def add_message(
    *,
    stock_locate: int,
    tracking_number: int,
    timestamp: int,
    reference: int,
    side: str,
    shares: int,
    stock: str,
    price: int,
) -> bytes:
    return itch_message(
        "A",
        stock_locate,
        tracking_number,
        timestamp,
        pack(
            ">QcI8sI",
            reference,
            side.encode("ascii"),
            shares,
            stock.encode().ljust(8),
            price,
        ),
    )


def stock_directory_message(
    *,
    stock_locate: int,
    tracking_number: int,
    timestamp: int,
    stock: str,
) -> bytes:
    return itch_message(
        "R",
        stock_locate,
        tracking_number,
        timestamp,
        pack(
            ">8sccIcc2scccccIc",
            stock.encode().ljust(8),
            b"Q",
            b"N",
            100,
            b"N",
            b"C",
            b"C ",
            b"P",
            b"N",
            b"N",
            b"1",
            b"N",
            1,
            b"N",
        ),
    )


