def test_itch_source_is_reusable_and_exposes_typed_lazy_frames(
    itch_path: Path,
) -> None:
    source = itch.ItchSource(str(itch_path), "AAPL")

    assert isinstance(source, itch.ItchSource)
    assert Path(source) == itch_path
    assert source.path == str(itch_path)
    assert source.ticker == "AAPL"

    lazy_frame = source.to_lazy_frame()
    assert isinstance(lazy_frame, pl.LazyFrame)
    assert lazy_frame.collect_schema() == pl.Schema(
        {
            "message_type": pl.String,
            "stock_locate": pl.UInt32,
            "tracking_number": pl.UInt32,
            "timestamp": pl.Time,
            "stock": pl.String,
            "operation": pl.String,
            "reference": pl.UInt64,
            "new_reference": pl.UInt64,
            "side": pl.String,
            "shares": pl.UInt32,
            "price": pl.UInt32,
            "execution_price": pl.UInt32,
            "body": pl.String,
        }
    )

    first_read = lazy_frame.select("message_type", "operation").collect()
    second_read = source.to_lazy_frame().select("message_type", "operation").collect()
    assert first_read.equals(second_read)
    assert first_read.height == 9
    assert first_read["message_type"].to_list() == [
        "S",
        "R",
        "R",
        "A",
        "A",
        "X",
        "U",
        "E",
        "D",
    ]
    assert first_read["operation"].to_list() == [
        None,
        None,
        None,
        "add",
        "add",
        "cancel",
        "replace",
        "execute",
        "delete",
    ]

    limited = (
        source.to_lazy_frame()
        .filter(pl.col("operation").is_not_null())
        .select("stock", "operation")
        .head(2)
        .collect()
    )
    assert limited.to_dict(as_series=False) == {
        "stock": ["AAPL", "MSFT"],
        "operation": ["add", "add"],
    }
    assert source.to_lazy_frame().filter(pl.col("stock") == "ZZZZ").collect().is_empty()
    assert source.to_lazy_frame().head(2).collect()["message_type"].to_list() == [
        "S",
        "R",
    ]


