def test_adapted_messages_retain_full_polars_lazyframe_support(
    itch_path: Path,
) -> None:
    source = itch.ItchSource(str(itch_path), "AAPL")
    messages = source.adapt()

    assert isinstance(messages, itch.ReplayMessages)
    assert not hasattr(messages, "as_lazy_frame")
    assert isinstance(messages.to_lazy_frame(), pl.LazyFrame)
    assert messages.to_lazy_frame().collect().height == 6

    run = (
        messages.to_lazy_frame()
        .filter(pl.col("timestamp").is_between(time(8, 0), time(17, 0)))
        .with_columns(pl.col("stock").str.to_uppercase())
        .sort(["timestamp", "tracking_number"])
    )
    assert isinstance(run, pl.LazyFrame)
    assert run.select("stock").collect()["stock"].to_list() == [
        "AAPL",
        "MSFT",
        "AAPL",
        "AAPL",
        "AAPL",
        "MSFT",
    ]

    raw_aapl = source.to_lazy_frame().filter(
        (pl.col("stock") == "AAPL") & pl.col("operation").is_not_null()
    )
    assert raw_aapl.collect()["operation"].to_list() == [
        "add",
        "cancel",
        "replace",
        "execute",
    ]


