def test_replay_context_builds_all_available_ticker_books_in_one_pass(
    itch_path: Path,
) -> None:
    sources = itch.ItchSource.all_available(str(itch_path))
    assert [source.ticker for source in sources] == ["AAPL", "MSFT"]

    with ReplayContext(source=sources, collect_stats=True, cutoff_time=None) as books:
        assert books.keys() == ["aapl", "msft"]
        assert books.message_count == 6
        assert books["aapl"].best_bid == 1_020_000
        assert books["aapl"].orders.bids.visible_quantity == 50
        assert books["msft"].best_bid is None
        assert books["msft"].best_ask is None


