def test_replay_context_uses_native_source_book_and_live_level_views(
    itch_path: Path,
) -> None:
    context = ReplayContext(
        source=itch.ItchSource(str(itch_path), "AAPL"), collect_stats=True, cutoff_time=None
    )

    with pytest.raises(RuntimeError, match="must be entered"):
        _ = context["aapl"]

    with context as books:
        assert books is context
        assert len(books) == 1
        assert books.keys() == ["aapl"]
        assert "AAPL" in books
        assert books.message_count == 4
        assert books.skipped_message_count == 0

        apple_book = books["aapl"]
        assert apple_book.best_bid == 1_020_000
        assert apple_book.best_ask is None
        assert apple_book.orders.bids.order_count == 1
        assert apple_book.orders.bids.visible_quantity == 50
        assert apple_book.orders.asks.order_count == 0
        assert levels_lazy(apple_book.orders.bids).collect().to_dict(
            as_series=False
        ) == {
            "price": [1_020_000],
            "quantity": [50],
            "hidden_quantity": [0],
            "order_count": [1],
        }
        assert levels_lazy(apple_book.orders.bids).filter(
            pl.col("quantity") > 0
        ).select("price").collect().to_dict(as_series=False) == {"price": [1_020_000]}


