@pytest.mark.parametrize("collect_stats", [False, True])
@pytest.mark.parametrize("concurrent", [False, True])
@pytest.mark.parametrize(
    "cutoff",
    [
        datetime(2026, 1, 15, 13, 0, 2, tzinfo=UTC),
        datetime(2026, 7, 15, 12, 0, 2, tzinfo=UTC),
        datetime(2026, 7, 15, 8, 0, 2, tzinfo=ZoneInfo("America/New_York")),
        datetime(
            2026, 7, 15, 17, 30, 2, tzinfo=timezone(timedelta(hours=5, minutes=30))
        ),
    ],
)
def test_cutoff_is_inclusive_across_timezones_and_replay_modes(
    itch_path: Path, cutoff: datetime, collect_stats: bool, concurrent: bool
) -> None:
    options = {}
    if "concurrent" in signature(ReplayContext).parameters:
        options["concurrent"] = concurrent
    elif concurrent:
        pytest.skip("extension was built without concurrent replay")

    with ReplayContext(
        source=itch.ItchSource.all_available(str(itch_path)),
        cutoff_time=cutoff,
        collect_stats=collect_stats,
        **options,
    ) as books:
        assert books.cutoff_time == cutoff.astimezone(UTC)
        assert books["aapl"].best_bid == 1_010_000
        assert books["aapl"].orders.bids.visible_quantity == 75
        assert books["msft"].best_ask == 2_000_000
        assert books["msft"].orders.asks.visible_quantity == 50
        assert books.message_count == (3 if collect_stats else 0)


def test_none_and_omitted_cutoffs_replay_the_full_feed_after_source_reuse(
    itch_path: Path,
) -> None:
    source = itch.ItchSource(str(itch_path), "AAPL")
    with ReplayContext(
        source=source, cutoff_time=datetime(2026, 1, 15, 13, 0, 2, tzinfo=UTC)
    ) as partial:
        assert partial["aapl"].orders.bids.visible_quantity == 75
    for options in ({}, {"cutoff_time": None}):
        with ReplayContext(source=source, collect_stats=True, **options) as full:
            assert full.cutoff_time is None
            assert full.message_count == 4
            assert full["aapl"].best_bid == 1_020_000
            assert full["aapl"].orders.bids.visible_quantity == 50


def test_cutoff_preserves_microseconds_at_nanosecond_message_boundaries(
    tmp_path: Path,
) -> None:
    cutoff_ns = (8 * 3_600 + 2) * 1_000_000_000 + 321_817_000
    path = tmp_path / "precision.itch"
    path.write_bytes(
        stock_directory_message(
            stock_locate=1, tracking_number=1, timestamp=0, stock="AAPL"
        )
        + b"".join(
            add_message(
                stock_locate=1,
                tracking_number=reference + 1,
                timestamp=cutoff_ns + offset,
                reference=reference,
                side="B",
                shares=1,
                stock="AAPL",
                price=1_010_000,
            )
            for reference, offset in enumerate((-1, 0, 1), start=1)
        )
    )
    with ReplayContext(
        source=itch.ItchSource(str(path), "AAPL"),
        cutoff_time=datetime(
            2026, 7, 15, 8, 0, 2, 321_817, tzinfo=ZoneInfo("America/New_York")
        ),
        collect_stats=True,
    ) as books:
        assert books.message_count == 2
        assert books["aapl"].orders.bids.visible_quantity == 2


@pytest.mark.parametrize("fold", [0, 1])
def test_cutoff_normalization_respects_the_dst_fold(itch_path: Path, fold: int) -> None:
    cutoff = datetime(
        2026, 11, 1, 1, 30, tzinfo=ZoneInfo("America/New_York"), fold=fold
    )
    context = ReplayContext(
        source=itch.ItchSource(str(itch_path), "AAPL"), cutoff_time=cutoff
    )
    assert context.cutoff_time == datetime(2026, 11, 1, 5 + fold, 30, tzinfo=UTC)


class NoOffsetTimezone(tzinfo):
    def utcoffset(self, dt: datetime | None) -> None:
        return None


@pytest.mark.parametrize(
    "cutoff",
    [datetime(2026, 1, 15, 8), datetime(2026, 1, 15, 8, tzinfo=NoOffsetTimezone())],
)
def test_cutoff_rejects_naive_datetimes_at_construction(
    itch_path: Path, cutoff: datetime
) -> None:
    with pytest.raises(
        ValueError, match="cutoff_time must be a timezone-aware datetime"
    ):
        ReplayContext(source=itch.ItchSource(str(itch_path), "AAPL"), cutoff_time=cutoff)


@pytest.mark.parametrize(
    "cutoff", ["2026-01-15T13:00:02Z", 123, date(2026, 1, 15), time(8)]
)
def test_cutoff_rejects_non_datetime_values(itch_path: Path, cutoff: object) -> None:
    with pytest.raises(TypeError):
        ReplayContext(source=itch.ItchSource(str(itch_path), "AAPL"), cutoff_time=cutoff)


@pytest.mark.parametrize("collect_stats", [False, True])
def test_replay_feather_sink_stays_connected_for_followup_fills(
    itch_path: Path, tmp_path: Path, collect_stats: bool
) -> None:
    from uuid import UUID

    from lobo.orders import MarketOrder, Side
    from lobo.sinks import FeatherSink, read_feather

    sink = FeatherSink(tmp_path / "replay.feather", batch_size=2)
    with ReplayContext(
        source=itch.ItchSource(str(itch_path), "AAPL"),
        collect_stats=collect_stats,
        sinks=[sink],
    ) as books:
        books["aapl"].fill(MarketOrder(10, UUID(int=1), Side.Sell))
        assert not sink.finished
    frame = pl.read_ipc(sink.path)
    assert frame.equals(read_feather(sink))
    assert frame["visible_quantity"].to_list() == [100, 75, 0, 80, 50, 40]
    assert frame["sequence_number"].to_list() == [1, 2, 3, 4, 5, 6]
    assert frame["book_id"].n_unique() == 1
    assert sink.finished
